// @generated by:gauntlet run:godseye-local-broker
import { randomUUID } from "node:crypto";
import { setTimeout as delay } from "node:timers/promises";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import type { AccessScope } from "../packages/core/src/access-provider.js";
import {
  BAO_BROKER_POLICY,
  baoPath,
  compileBrokerPolicy,
  compileCellPolicy,
} from "../packages/core/src/bao-policy.js";
import { BaoAccessProvider } from "../packages/core/src/bao-provider.js";
import { type OpenBaoFixture, openBaoFixture } from "./openbao-fixture.js";

function scope(): AccessScope {
  return {
    projectId: randomUUID(),
    environmentId: randomUUID(),
    purpose: "runtime",
    id: randomUUID(),
    slotId: randomUUID(),
  };
}
function envelope() {
  return { value: randomUUID(), operationId: randomUUID(), fingerprint: "a".repeat(64) };
}
function authObject(body: Record<string, unknown>) {
  const auth = body.auth;
  if (
    !auth ||
    typeof auth !== "object" ||
    !("client_token" in auth) ||
    typeof auth.client_token !== "string" ||
    !("accessor" in auth) ||
    typeof auth.accessor !== "string"
  )
    throw new Error("OpenBao lab did not issue the expected authentication shape");
  return { proof: auth.client_token, accessor: auth.accessor };
}

describe("pinned real OpenBao provider boundary", () => {
  let lab: OpenBaoFixture;
  let provider: BaoAccessProvider;
  const retained = scope();
  const retainedEnvelope = envelope();
  const policyText = compileBrokerPolicy();
  const issue = async (policies: string[], ttl = "1h", noDefaultPolicy = true) => {
    const issued = await lab.admin("/auth/token/create", {
      method: "POST",
      body: { policies, no_default_policy: noDefaultPolicy, ttl, renewable: false },
    });
    if (issued.status !== 200)
      throw new Error("OpenBao lab scoped authentication provisioning failed");
    return authObject(issued.body);
  };
  beforeAll(async () => {
    lab = await openBaoFixture();
    await lab.unseal();
    const mounted = await lab.admin("/sys/mounts/godseye", {
      method: "POST",
      body: { type: "kv", options: { version: "2" } },
    });
    const policy = await lab.admin(`/sys/policies/acl/${BAO_BROKER_POLICY}`, {
      method: "PUT",
      body: { policy: policyText },
    });
    if (mounted.status !== 204 || policy.status !== 204)
      throw new Error("OpenBao lab mount/policy setup failed");
    const controller = await issue([BAO_BROKER_POLICY]);
    provider = new BaoAccessProvider({ address: lab.url, proof: () => controller.proof });
    await provider.write(retained, retainedEnvelope, 0);
  }, 90_000);
  afterAll(async () => {
    await lab?.close();
  }, 30_000);

  it("T-AC-18 T08 enforces actual compiled per-cell policies against direct foreign and privileged requests", async () => {
    const owned = scope();
    const foreign = { ...owned, environmentId: randomUUID() };
    const otherPurpose = { ...owned, purpose: "migration" as const };
    await provider.write(owned, envelope(), 0);
    await provider.write(foreign, envelope(), 0);
    await provider.write(otherPurpose, envelope(), 0);
    const name = `fixture-${randomUUID()}`;
    await lab.admin(`/sys/policies/acl/${name}`, {
      method: "PUT",
      body: { policy: compileCellPolicy([owned]) },
    });
    const authentication = await issue([name]);

    expect((await lab.request(`/${baoPath(owned)}`, { proof: authentication.proof })).status).toBe(
      200,
    );
    for (const path of [
      `/${baoPath(foreign)}`,
      `/${baoPath(otherPurpose)}`,
      "/godseye/metadata/cells",
      "/sys/mounts",
      "/sys/policies/acl/godseye-broker-v1",
    ])
      expect((await lab.request(path, { proof: authentication.proof })).status).toBe(403);
    expect(
      (
        await lab.request("/auth/token/create", {
          method: "POST",
          proof: authentication.proof,
          body: { policies: [BAO_BROKER_POLICY] },
        })
      ).status,
    ).toBe(403);
    expect(
      (
        await lab.request(`/${baoPath(owned)}`, {
          method: "POST",
          proof: authentication.proof,
          body: { data: envelope() },
        })
      ).status,
    ).toBe(403);
  });

  it("T-AC-18 T08 rejects stale provider CAS while preserving current and explicitly selected prior versions", async () => {
    const target = scope();
    const previous = envelope();
    const next = envelope();
    expect(await provider.write(target, previous, 0)).toBe(1);
    expect(await provider.write(target, next, 1)).toBe(2);
    await expect(provider.write(target, envelope(), 1)).rejects.toMatchObject({
      code: "PROVIDER_CONFLICT",
    });

    expect((await provider.read(target))?.version).toBe(2);
    expect((await provider.read(target, 1))?.value === previous.value).toBe(true);
    expect((await provider.read(target, 2))?.value === next.value).toBe(true);
  });

  it("T-AC-18 T08 rejects extra/default policy and actual controller-policy privilege drift", async () => {
    const broad = await issue([BAO_BROKER_POLICY], "1h", false);
    const unsafe = new BaoAccessProvider({ address: lab.url, proof: () => broad.proof });
    expect((await unsafe.health()).state).toBe("unauthorized");
    try {
      await lab.admin(`/sys/policies/acl/${BAO_BROKER_POLICY}`, {
        method: "PUT",
        body: { policy: `${policyText}\npath "*" { capabilities = ["sudo", "read"] }` },
      });
      expect((await provider.health()).state).toBe("unauthorized");
    } finally {
      await lab.admin(`/sys/policies/acl/${BAO_BROKER_POLICY}`, {
        method: "PUT",
        body: { policy: policyText },
      });
    }
    expect((await provider.health()).state).toBe("ready");
  });

  it("T-AC-18 T08 refuses an actual root provider configuration", async () => {
    const privileged = await issue(["root"]);
    const unsafe = new BaoAccessProvider({ address: lab.url, proof: () => privileged.proof });
    expect((await unsafe.health()).state).toBe("unauthorized");
  });

  it("T-AC-18 T08 blocks new access while sealed without changing retained consumer material", async () => {
    const mounted = (await provider.read(retained))?.value;
    expect(mounted === retainedEnvelope.value).toBe(true);
    try {
      expect((await lab.seal()).status).toBe(204);
      expect((await provider.health()).state).toBe("sealed");
      await expect(provider.read(retained)).rejects.toMatchObject({
        code: "CAPABILITY_UNAVAILABLE",
      });
      await expect(provider.write(retained, envelope(), 1)).rejects.toMatchObject({
        code: "CAPABILITY_UNAVAILABLE",
      });
      expect(mounted === retainedEnvelope.value).toBe(true);
    } finally {
      await lab.unseal();
    }
    expect((await provider.read(retained))?.value === mounted).toBe(true);
  }, 60_000);

  it("T-AC-18 T31 cold-starts sealed and recovers encrypted Raft material using independent in-memory shares", async () => {
    await lab.restart();
    expect((await lab.health()).body.sealed).toBe(true);
    expect((await provider.health()).state).toBe("sealed");
    await lab.unseal();

    expect((await provider.health()).state).toBe("ready");
    expect((await provider.read(retained))?.value === retainedEnvelope.value).toBe(true);
  }, 60_000);

  it("T08 T22 revokes one actual scoped OpenBao proof without affecting another", async () => {
    const name = `fixture-${randomUUID()}`;
    await lab.admin(`/sys/policies/acl/${name}`, {
      method: "PUT",
      body: { policy: compileCellPolicy([retained]) },
    });
    const revoked = await issue([name]);
    const surviving = await issue([name]);
    const path = `/${baoPath(retained)}`;
    expect((await lab.request(path, { proof: revoked.proof })).status).toBe(200);
    expect(
      (
        await lab.admin("/auth/token/revoke-accessor", {
          method: "POST",
          body: { accessor: revoked.accessor },
        })
      ).status,
    ).toBe(204);

    expect((await lab.request(path, { proof: revoked.proof })).status).toBe(403);
    expect((await lab.request(path, { proof: surviving.proof })).status).toBe(200);
  });

  it("T08 T22 expires a short nonrenewable actual OpenBao proof", async () => {
    const name = `fixture-${randomUUID()}`;
    await lab.admin(`/sys/policies/acl/${name}`, {
      method: "PUT",
      body: { policy: compileCellPolicy([retained]) },
    });
    const short = await issue([name], "1s");
    const path = `/${baoPath(retained)}`;
    expect((await lab.request(path, { proof: short.proof })).status).toBe(200);
    await delay(1500);
    expect((await lab.request(path, { proof: short.proof })).status).toBe(403);
  });
});
